inline std::string te_get_yoga_text(std::string yoga_name) {
    if (yoga_name == "Ruchaka") return "రుచక యోగం: కుజుడు కేంద్రంలో స్వక్షేత్రం లేదా ఉచ్ఛ స్థితిలో ఉన్నాడు. ఇది అపారమైన ధైర్యం, సహజ నాయకత్వం మరియు రియల్ ఎస్టేట్/సాంకేతిక రంగాల్లో తిరుగులేని విజయాన్ని ఇస్తుంది.";
    if (yoga_name == "Bhadra") return "భద్ర యోగం: బుధుడు కేంద్రంలో స్వక్షేత్రం లేదా ఉచ్ఛ స్థితిలో ఉన్నాడు. ఇది అసాధారణమైన మేధస్సును, వ్యాపార దక్షతను, మరియు అద్భుతమైన కమ్యూనికేషన్ స్కిల్స్ ఇస్తుంది.";
    if (yoga_name == "Hamsa") return "హంస యోగం: గురుడు కేంద్రంలో స్వక్షేత్రం లేదా ఉచ్ఛ స్థితిలో ఉన్నాడు. ఇది జాతకుడికి అపారమైన జ్ఞానం, సమాజంలో గొప్ప గౌరవం, మరియు ధార్మిక ప్రవర్తనను ప్రసాదిస్తుంది.";
    if (yoga_name == "Malavya") return "మాళవ్య యోగం: శుక్రుడు కేంద్రంలో స్వక్షేత్రం లేదా ఉచ్ఛ స్థితిలో ఉన్నాడు. ఇది విలాసవంతమైన జీవితం, కళాత్మక నైపుణ్యం, ఆకర్షణ మరియు అద్భుతమైన వైవాహిక జీవితాన్ని గ్యారెంటీ చేస్తుంది.";
    if (yoga_name == "Sasa") return "శశ యోగం: శని కేంద్రంలో స్వక్షేత్రం లేదా ఉచ్ఛ స్థితిలో ఉన్నాడు. ఇది విపరీతమైన పట్టుదల, కష్టపడే తత్వం, మరియు భవిష్యత్తులో తిరుగులేని అధికారాన్ని ఇస్తుంది.";
    if (yoga_name == "Gajakesari") return "గజకేసరి యోగం: గురు మరియు చంద్రులు పరస్పరం కేంద్ర స్థానాల్లో ఉన్నారు. ఇది అపారమైన కీర్తి, అంతర్గత జ్ఞానం, మరియు జీవితంలో ఎన్ని కష్టాలనైనా జయించే మనోధైర్యాన్ని ఇస్తుంది.";
    if (yoga_name == "Budhaditya") return "బుధాదిత్య యోగం: సూర్య, బుధుల కలయిక. ఇది అత్యంత పదునైన విశ్లేషణాత్మక బుద్ధిని, అడ్మినిస్ట్రేటివ్ మరియు ఆర్గనైజేషనల్ స్కిల్స్‌ను ఇస్తుంది.";
    if (yoga_name == "ChandraMangala") return "చంద్ర-మంగళ యోగం: చంద్ర, కుజుల కలయిక. ఇది విశ్రాంతి లేని భావోద్వేగ తీవ్రతను, మరియు వేగంగా డబ్బు సంపాదించాలనే విపరీతమైన ఆశయాన్ని ఇస్తుంది.";
    return "";
}

inline std::string te_get_dosha_text(std::string dosha_name, int p1, int p2) {
    if (dosha_name == "Kuja") return "మంగళ (కుజ) దోషం: కుజుడు లగ్నం నుండి " + std::to_string(p1) + "వ భావంలో మరియు చంద్రుని నుండి " + std::to_string(p2) + "వ భావంలో ఉన్నాడు.\n    * ప్రభావం: ఈ దూకుడు శక్తి భాగస్వామ్యాల్లో తీవ్రమైన ఘర్షణను సృష్టిస్తుంది. జీవిత భాగస్వామికి కూడా ఈ దోషం ఉంటే ఇది రద్దు అవుతుంది, లేదా 28 ఏళ్ల తర్వాత దీని ప్రభావం తగ్గుతుంది.";
    if (dosha_name == "KalaSarpa") return "కాల సర్ప దోషం: అన్ని ప్రధాన గ్రహాలు రాహు, కేతువుల అక్షం (యాక్సిస్) మధ్య బందీ అయ్యాయి.\n    * ప్రభావం: ఇది జీవితంలో తీవ్రమైన హెచ్చుతగ్గులను సృష్టిస్తుంది. జీవిత ప్రథమార్థంలో అడ్డంకులు, ఆలస్యాలు ఎదురైనా, ద్వితీయార్ధంలో (33 ఏళ్ల తర్వాత) అపారమైన విజయాన్ని ఇస్తుంది.";
    return "";
}

// =========================================================================
// GOCHARA PHALA MATRIX (TRANSIT PREDICTIONS FROM MOON SIGN)
// =========================================================================

inline std::string te_get_gochar_text(int p_idx, int from_mo) {
    if (p_idx == 5) { // GURU (Jupiter)
        switch(from_mo) {
            case 1: return "జన్మ రాశిలో గురు సంచారం: స్థాన చలనం, అకారణంగా మనస్థాపం, పై అధికారులతో లేదా ఇష్టమైన వారితో మనస్పర్థలు రావచ్చు. ఖర్చులు పెరుగుతాయి.";
            case 2: return "2వ ఇంట గురు సంచారం: అత్యంత శుభకరం. కుటుంబంలో సంతోషం, ఆర్థిక లాభాలు, మీరు చేసే పనులకు గొప్ప గుర్తింపు, ఆస్తుల వృద్ధి జరుగుతుంది.";
            case 3: return "3వ ఇంట గురు సంచారం: వృత్తిలో అడ్డంకులు, స్థాన మార్పులు లేదా బదిలీలు, తోబుట్టువులతో స్వల్ప విభేదాలు రావచ్చు.";
            case 4: return "4వ ఇంట గురు సంచారం: గృహంలో అశాంతి, తల్లి ఆరోగ్య సమస్యలు, లేదా ఆస్తుల విషయాల్లో చికాకులు ఏర్పడతాయి.";
            case 5: return "5వ ఇంట గురు సంచారం: అత్యంత శుభకరం. వివాహం జరగడానికి, సంతాన ప్రాప్తికి, కొత్త ఇల్లు/వాహనాలు కొనడానికి, వ్యాపారంలో భారీ లాభాలకు ఇది అద్భుతమైన సమయం.";
            case 6: return "6వ ఇంట గురు సంచారం: అనారోగ్య సమస్యలు, అప్పుల బాధలు, లేదా శత్రువుల వలన అకారణంగా భయం ఏర్పడుతుంది.";
            case 7: return "7వ ఇంట గురు సంచారం: అత్యంత శుభకరం. అవివాహితులకు వివాహ ప్రాప్తి. వృత్తి/వ్యాపారాల్లో అద్భుతమైన లాభాలు, ఆరోగ్య వృద్ధి, దాంపత్య సౌఖ్యం లభిస్తాయి.";
            case 8: return "8వ ఇంట గురు సంచారం: అనారోగ్యం, ఊహించని ధన నష్టం, ప్రయాణాల్లో అలసట, పనులలో తీవ్రమైన జాప్యం జరుగుతుంది.";
            case 9: return "9వ ఇంట గురు సంచారం: అత్యంత శుభకరం. అపారమైన అదృష్టం, పుణ్యక్షేత్ర దర్శనం, విదేశీ ప్రయాణాలు, మరియు సంపద వృద్ధి చెందుతాయి.";
            case 10: return "10వ ఇంట గురు సంచారం: వృత్తిలో ఆకస్మిక మార్పులు, ఉద్యోగ భయం లేదా బదిలీ, వ్యాపారంలో నష్టాలు వచ్చే అవకాశం ఉంది.";
            case 11: return "11వ ఇంట గురు సంచారం: అత్యంత శుభకరం. మీరు కోరుకున్న ప్రతి కోరిక నెరవేరుతుంది. భారీ ఆర్థిక లాభాలు, ప్రమోషన్లు, ఇంట్లో శుభకార్యాలు జరుగుతాయి.";
            case 12: return "12వ ఇంట గురు సంచారం: శుభకార్యాల కోసం (వివాహం, గృహ నిర్మాణం) భారీగా డబ్బు ఖర్చు చేస్తారు. దూర ప్రయాణాలు గోచరిస్తున్నాయి.";
        }
    }
    else if (p_idx == 7) { // SHANI (Saturn)
        switch(from_mo) {
            case 1: return "జన్మ శని (ఏలినాటి శని మధ్య దశ): తీవ్రమైన మానసిక ఆందోళన, శారీరక అలసట, వృత్తిలో అధిక శ్రమ, మరియు అనారోగ్యం గోచరిస్తుంది.";
            case 2: return "2వ ఇంట శని (ఏలినాటి శని చివరి దశ): ఆర్థిక ఇబ్బందులు, కుటుంబంలో గొడవలు, మరియు ఆకస్మిక ధన నష్టం జరిగే అవకాశం ఉంది.";
            case 3: return "3వ ఇంట శని: అత్యంత శుభకరం. మీ ధైర్యసాహసాలు పెరుగుతాయి. శత్రు నాశనం, నూతన ఉద్యోగ లేదా ఆస్తి ప్రాప్తి, అఖండ విజయం వరిస్తుంది.";
            case 4: return "4వ ఇంట శని (అర్ధాష్టమ శని): గృహంలో అశాంతి, తల్లికి అనారోగ్యం, వృత్తిపరమైన చికాకులు, మరియు బంధువులతో విభేదాలు ఏర్పడతాయి.";
            case 5: return "5వ ఇంట శని: సంతానం గురించి ఆందోళన, పెట్టుబడుల్లో నష్టాలు, ప్రేమ వ్యవహారాల్లో అపార్థాలు రావచ్చు.";
            case 6: return "6వ ఇంట శని: అత్యంత శుభకరం. కోర్టు కేసులు, శత్రువులు, రోగాలపై తిరుగులేని విజయం. అప్పులు తీరిపోయి, ఆర్థికంగా పుంజుకుంటారు.";
            case 7: return "7వ ఇంట శని: జీవిత భాగస్వామితో తీవ్రమైన అపార్థాలు, వ్యాపార భాగస్వాములతో గొడవలు, వృథా ప్రయాణాలు గోచరిస్తున్నాయి.";
            case 8: return "8వ ఇంట శని (అష్టమ శని): వృత్తిలో ఆకస్మిక అడ్డంకులు, తీవ్ర అనారోగ్యం, మరియు ఊహించని కష్టాలు ఎదురవుతాయి. జాగ్రత్త అవసరం.";
            case 9: return "9వ ఇంట శని: తండ్రికి అనారోగ్యం, ధార్మిక కార్యక్రమాలకు దూరమవడం, మరియు పనులలో నిరాశ నిస్పృహలు కలుగుతాయి.";
            case 10: return "10వ ఇంట శని: వృత్తిలో (కెరీర్) తీవ్రమైన పని భారం పెరుగుతుంది. అధికారులతో విభేదాలు, శ్రమకు తగిన గుర్తింపు రాకపోవడం జరుగుతుంది.";
            case 11: return "11వ ఇంట శని: అత్యంత శుభకరం. అన్ని విధాలుగా ఆర్థిక లాభాలు, నూతన గృహ/వాహన ప్రాప్తి, సంఘంలో గొప్ప గౌరవం దక్కుతాయి.";
            case 12: return "12వ ఇంట శని (ఏలినాటి శని ప్రారంభం): వృథా ఖర్చులు, నిద్రలేమి, నేత్ర లేదా పాదాల నొప్పులు, మరియు ఊహించని ప్రయాణాలు వస్తాయి.";
        }
    }
    else if (p_idx == 8 || p_idx == 9) { // RAHU & KETU
        if (from_mo == 3 || from_mo == 6 || from_mo == 11) {
            return "ఉపచయ స్థానంలో ఛాయా గ్రహ సంచారం: ఇది అత్యంత అనుకూలమైన సమయం. అకస్మాత్తుగా భారీ లాభాలు, విదేశీ ప్రయాణాలు, మరియు శత్రు నాశనం జరుగుతాయి.";
        } else {
            return "ఈ ఛాయా గ్రహ సంచారం మానసిక గందరగోళాన్ని, ఆకస్మిక మార్పులను మరియు సంబంధిత భావంలో కొంత అస్థిరతను సృష్టిస్తుంది.";
        }
    }
    
    // Default fallback for Sun, Moon, Mars, Mercury, Venus (Fast moving planets)
    if (from_mo == 3 || from_mo == 6 || from_mo == 10 || from_mo == 11) {
        return "చంద్రుని నుండి శుభ స్థానంలో సంచారం. పనుల్లో విజయం, లాభాలు, అనుకూల వాతావరణం ఏర్పడుతుంది.";
    } else {
        return "సాధారణ ఫలితాలు. పనులలో స్వల్ప జాప్యం లేదా సాధారణ శ్రమ ఉంటుంది.";
    }
}

// =========================================================================
// NEW: DYNAMIC VIMSHOTTARI DASHA PREDICTIONS (TELUGU)
// =========================================================================

inline std::string te_get_dynamic_mahadasha(int p_idx, int score, int house) {
    std::string base = "";
    switch(p_idx) {
        case 1: base = "ఇది మీ జీవితంలో అధికార వృద్ధి, ప్రభుత్వ లేదా ఉన్నత స్థాయి వర్గాల నుండి లాభాలు పొందే కాలం. నాయకత్వ లక్షణాలు పెరుగుతాయి, తండ్రితో సంబంధాలు కీలకం అవుతాయి."; break;
        case 2: base = "ఇది మానసిక, భావోద్వేగ మరియు కళాత్మక పరివర్తనలకు సంబంధించిన కాలం. ప్రయాణాలు, స్థాన మార్పులు, మాతృ సౌఖ్యం, మరియు పబ్లిక్ రిలేషన్స్ వృద్ధి చెందుతాయి."; break;
        case 3: base = "అత్యంత శక్తివంతమైన, వేగవంతమైన కాలం. రియల్ ఎస్టేట్, ఆస్తుల కొనుగోలు, సోదరుల మద్దతు లభిస్తుంది. ధైర్యం పెరుగుతుంది, కానీ కోపం పట్ల జాగ్రత్త వహించాలి."; break;
        case 4: base = "మేధోపరమైన వృద్ధి, వ్యాపార విస్తరణ, ఉన్నత విద్యాభ్యాసానికి ఇది అద్భుతమైన కాలం. కమ్యూనికేషన్, ఐటీ, నెట్‌వర్కింగ్ ద్వారా భారీ ఆర్థిక లాభాలు వస్తాయి."; break;
        case 5: base = "ఇది జీవితంలో అత్యంత పురోగతి, అదృష్టం, మరియు ధార్మికతను ఇచ్చే స్వర్ణయుగం. వివాహం, సంతాన ప్రాప్తి, సంపద వృద్ధి, మరియు సమాజంలో గొప్ప గౌరవం దక్కుతాయి."; break;
        case 6: base = "విలాసవంతమైన జీవితం, కళలు, ప్రేమ, మరియు భౌతిక సుఖాలను అనుభవించే సుదీర్ఘ కాలం. వాహనాలు, గృహ ప్రాప్తి, మరియు స్త్రీల సహాయంతో ఆర్థిక పురోగతి లభిస్తుంది."; break;
        case 7: base = "క్రమశిక్షణ, కఠిన శ్రమ, మరియు కర్మల ఫలితాలను ఇచ్చే కాలం. ప్రారంభంలో ఆటంకాలు ఉన్నప్పటికీ, ఓర్పుతో పనిచేస్తే జీవితంలో శాశ్వత స్థిరత్వాన్ని నిర్మిస్తారు."; break;
        case 8: base = "ఊహించని, ఆకస్మిక మార్పులకు మారుపేరు ఈ దశ. విదేశీ ప్రయాణాలు, పాలిటిక్స్ లేదా టెక్నాలజీలో ఆకస్మిక ఎత్తుపల్లాలు ఉంటాయి. భౌతిక కోరికలు విపరీతంగా పెరుగుతాయి."; break;
        case 9: base = "భౌతిక ప్రపంచం పట్ల కొంత వైరాగ్యం, ఆధ్యాత్మిక చింతన, మరియు అంతర్గత అన్వేషణ జరిగే కాలం. పాత సంబంధాలు లేదా కెరీర్ ముగిసి కొత్తవి ప్రారంభం కావచ్చు."; break;
    }

    std::string modifier = "";
    if (score >= 3) modifier += "మీ జాతకంలో ఈ గ్రహం అత్యంత బలమైన స్థితిలో ఉంది. కాబట్టి ఈ దశలో మీకు అపారమైన అదృష్టం, స్పష్టత మరియు ఏ ఆటంకం లేని గొప్ప విజయాలు సిద్ధిస్తాయి. ";
    else if (score <= -2) modifier += "అయితే, ఈ గ్రహం బలహీనంగా లేదా ప్రతికూల స్థితిలో ఉన్నందున, ఈ దశలో విపరీతమైన ఓర్పు అవసరం. పనులలో జాప్యం లేదా ఒత్తిడి రావచ్చు; తగిన పరిహారాలు చేసుకోవడం మంచిది. ";

    if (house == 6 || house == 8 || house == 12) modifier += "ఈ గ్రహం దుస్థానంలో (6, 8, 12) ఉండటం వల్ల, ఈ దశ పాత కర్మలను క్లియర్ చేయడానికి, అడ్డంకులను అధిగమించడానికి దారితీస్తుంది.";
    else if (house == 1 || house == 4 || house == 7 || house == 10) modifier += "కేంద్ర స్థానంలో ఉండటం వల్ల, ఈ దశ అత్యంత చురుకుగా ఉంటుంది. మీ కెరీర్, గృహం లేదా భాగస్వామ్యాల్లో కంటికి కనిపించే భారీ మార్పులు జరుగుతాయి.";
    else if (house == 5 || house == 9) modifier += "త్రికోణ స్థానంలో ఉన్నందున, ఈ దశ మీకు దైవానుగ్రహాన్ని, సహజమైన అదృష్టాన్ని మరియు పూర్వ జన్మ సుకృతాన్ని అందిస్తుంది.";
    else if (house == 3 || house == 11) modifier += "ఉపచయ స్థానంలో ఉండటం వల్ల, ప్రారంభంలో విపరీతమైన శ్రమ ఉన్నప్పటికీ, కాలక్రమేణా భారీ ఆర్థిక లాభాలు వృద్ధి చెందుతాయి.";
    
    return base + "\n   " + modifier;
}

